! ============================================================
! VML 条件变量扩展库 — Fortran
!
! 使用示例:
!   call asm("SYSCALL 313")   ! 创建条件变量
!   call asm("SYSCALL 314")   ! 等待条件变量
!   call asm("SYSCALL 315")   ! 唤醒单个等待者
!   call asm("SYSCALL 316")   ! 唤醒所有等待者
!
! 注意: 仅在 OS 模式 (--mode os) 下可用
! ============================================================

! ============================================================
! SYSCALL 313 — CondCreate
! 创建条件变量
! 参数: 无
! 返回值: R0 = 条件变量 ID (>0 成功)
! 条件变量 ID 由系统分配，用于后续操作
! ============================================================

! ============================================================
! SYSCALL 314 — CondWait
! 等待条件变量（自动释放关联的互斥锁）
! 参数:
!   R0 = 条件变量 ID
!   R1 = 互斥锁 ID
! 返回值: R0 = 0 成功
!
! 注意: 当前为 stub，返回 NOT_SUPPORTED
! ============================================================

! ============================================================
! SYSCALL 315 — CondSignal
! 唤醒一个等待该条件变量的线程
! 参数: R0 = 条件变量 ID
! 返回值: R0 = 0 成功
!
! 注意: 当前为 stub
! ============================================================

! ============================================================
! SYSCALL 316 — CondBroadcast
! 唤醒所有等待该条件变量的线程
! 参数: R0 = 条件变量 ID
! 返回值: R0 = 0 成功
!
! 注意: 当前为 stub
! ============================================================

! ============================================================
! 使用模式示例（概念性代码）:
!
! program cond_example
!   implicit none
!   ! 1. 创建互斥锁
!   call asm("SYSCALL 310")
!   !   此时 R0 包含 mutex_id
!
!   ! 2. 创建条件变量
!   call asm("SYSCALL 313")
!   !   此时 R0 包含 cond_id
!
!   ! 3. 生产者线程:
!   !   call asm("SYSCALL 311")   ! MutexLock
!   !   ... 修改共享数据 ...
!   !   call asm("SYSCALL 316")   ! CondBroadcast
!   !   call asm("SYSCALL 312")   ! MutexUnlock
!
!   ! 4. 消费者线程:
!   !   call asm("SYSCALL 311")   ! MutexLock
!   !   call asm("SYSCALL 314")   ! CondWait
!   !   ... 读取共享数据 ...
!   !   call asm("SYSCALL 312")   ! MutexUnlock
! end program cond_example
! ============================================================
